import 'package:flutter/material.dart';import '../models/models.dart';import '../services/data_service.dart';
class ProductsScreen extends StatelessWidget{final bool admin;ProductsScreen({super.key,required this.admin});final ds=DataService();void add(BuildContext c,[Product? old]){final n=TextEditingController(text:old?.name),code=TextEditingController(text:old?.code),cat=TextEditingController(text:old?.category),unit=TextEditingController(text:old?.units.isNotEmpty==true?old!.units.first.name:'قطعة');showDialog(context:c,builder:(_)=>AlertDialog(title:Text(old==null?'إضافة صنف':'تعديل صنف'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'اسم الصنف')),TextField(controller:code,decoration:const InputDecoration(labelText:'الكود')),TextField(controller:cat,decoration:const InputDecoration(labelText:'التصنيف')),TextField(controller:unit,decoration:const InputDecoration(labelText:'الوحدة الأساسية'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:()async{await ds.saveProduct(Product(id:old?.id??'',name:n.text,code:code.text,category:cat.text,units:[UnitOption(unit.text,1)]));if(c.mounted)Navigator.pop(c);},child:const Text('حفظ'))]));}
@override Widget build(BuildContext c)=>StreamBuilder<List<Product>>(stream:ds.products(),builder:(c,s){final all=s.data??[];return Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'ابحث بالاسم أو الكود'),onChanged:(_){ })),Expanded(child:ListView.builder(itemCount:all.length,itemBuilder:(c,i){final p=all[i];return Card(child:ListTile(title:Text(p.name),subtitle:Text('${p.code} • ${p.category} • ${p.units.map((x)=>x.name).join(', ')}'),trailing:admin?Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>add(c,p),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>ds.deleteProduct(p.id),icon:const Icon(Icons.delete_outline))]):null);}))]),floatingActionButton:admin?FloatingActionButton(onPressed:()=>add(c),child:const Icon(Icons.add)):null);});}
